use vstd::prelude::*;

verus! {

spec fn rev_index(n: nat, j: nat) -> nat {
    // for j in 0..n, gives the source index in `a` for `a_rev[j]`
    n - 1 - j
}

fn reverse(a: &Vec<i32>) -> (a_rev: Vec<i32>)
    ensures
        a_rev.len() == a.len(),
        forall|j: int|
            0 <= j < a.len() ==> a_rev[j] == a[rev_index(a.len() as nat, j as nat) as int],
{
    let n = a.len();
    let mut a_rev = Vec::with_capacity(n);

    for i in (0..n).rev()
        invariant
            a_rev.len() <= n,
            // exactly n - (i+1) elements have been pushed so far
            a_rev.len() == n - (i + 1),
            // prefix correctness: pushed elements are the last elements of `a` in order
            forall|j: int|
                0 <= j < a_rev.len() ==>
                    a_rev[j] == a[rev_index(n as nat, j as nat) as int],
    {
        a_rev.push(a[i]);
    }

    a_rev
}

} // verus!

